	"view in browser",
	"view this email",
	"view in your browser",
	"view email in browser",
	"view online",
	"view it online",
	"see it in your browser",
	"read online",
	"read in browser",
	"web version",
];

const SHARE_MARKERS = [
	"twitter.com/intent",
	"x.com/intent",
	"facebook.com/sharer",
	"linkedin.com/share",
	"t.me/share",
